    dateToTimeTable: function(date, sperator) {
        var me = this,
            vm = me.getViewModel();
        var refs = me.getReferences();

        var year = date.getFullYear();
        var month = date.getMonth()+1;
        month = month < 10 ? "0" + month: month;
        var day = date.getDate();
        day = day < 10 ? "0" + day: day;

        return year +sperator + month +sperator +  day;
    },

    reqServer: function(afterchange, aplyYn) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            approvalLineGrid = refs.approvalLineGrid;

        // 결재이력데이터조회
        Ext.Ajax.request({
            headers : {
                serviceId : 'HwmHodSvc.findAllHwmHodAply',
                viewId : 'HwmHodAply02M'
            },
            scope : me,
            jsonData :afterchange,
            success : function(response) {
                var ob = JSON.parse(response.responseText);
                var row1Cnt,row2Cnt,row3Cnt,row4Cnt, row5Cnt;
                var cont =ob.page.content;


                for(var i in cont){
                    var name = cont[i].name;

                    if(name == 'f'){
                        row1Cnt = cont[i].total;
                    }else if(name == 'd'){
                        row2Cnt = cont[i].total;
                    }else if(name == 'yuhyo'){
                        row4Cnt = cont[i].total;
                    }else if(name =='mth'){
                        row5Cnt = cont[i].total;
                    }else{
                        row3Cnt = cont[i].total;
                    }
                }

                if(row5Cnt > 0){
                    Ext.Msg.alert('확인','월근태 결재 내역이 있습니다. <br/> 결재를 취소한 뒤 신청 부탁드리겠습니다.');
                    return;
                }

                var edocCd = vm.get('docCd');
                var docNm = vm.get('docNm');
                var bizServiceId = 'HwmHodSvc.saveHwmHodAply';
                if(refs.aplDvcd.getValue() == '01' && row1Cnt > 0){
                    Ext.Msg.alert('확인','이미 승인된 이력이 있습니다.');
                    return;

                }

                //         if(refs.aplDvcd.getValue() == '02' && row1Cnt == 0){
                //             Ext.Msg.alert('확인','취소할 내역이 없습니다. 확인 부탁드리겠습니다.');
                //             return;
                //         }

                if(refs.aplDvcd.getValue() == '01' && row2Cnt > 0){
                    Ext.Msg.alert('확인','이미 신청된 이력이 있습니다.');
                    return;
                }


                if(row3Cnt > 0 && afterchange.aplDvcd == Constants.wrkAplDvcd.APPLY ){
                    Ext.Msg.alert('확인','관리자가 수정한 내역이 있습니다. <br/> 관리자에게 확인 부탁드리겠습니다.');
                    return;
                }

                if(row4Cnt !== 0 && afterchange.aplDvcd == Constants.wrkAplDvcd.APPLY ){
                    Ext.Msg.alert('확인','휴일에만 휴일근무를 신청 할 수 있습니다 <br/> 관리자에게 문의해주십시오.');
                    return;
                }

                if(aplyYn){
                    if(refs.aplDvcd.getValue() == "02"){
                        // 휴일근무 신청취소
                        var params = {};
                        var docData = {
                            afterchange : afterchange
                        };
                        params.aprStcd = '09'; // 완료처리
                        params.aplDvcd = '02';
                        params.docData = docData;

                        // Service 호출
                        Ext.Ajax.request({
                            headers : {
                                viewId : this.getView().xtype, // userAlias
                                serviceId : bizServiceId // 조건 검사 후 출.퇴근 처리
                            },
                            jsonData : params,
                            scope : me,
                            success : function(response) {
                                me.onComplete();
                            },
                            failure : function(response, opts){
                            }
                        });
                    } else {
                        // 휴일근무 신청
                        if(!refs.aplCntn.getValue() || refs.aplCntn.getValue().length < 50){
                            Ext.Msg.alert('확인', '사유를 50자 이상 입력해주세요.');
                            return false;
                        }

                        // + 버튼이 아님(formValid 에서 필요)
                        afterchange.btnPlus = false;
                        var errMsg = this.formValid(afterchange);
                        if(errMsg.length > 0){
                            Ext.Msg.alert('입력값을 확인해주세요.', errMsg);
                            return false;
                        }
                        ApprovalBoxSvc.draft({
                            scope                 : me,
                            edocCd                : edocCd,				 	 		// 전자문서관리에서 설정된 문서코드: 화면ID를 사용함
                            docNm                 : docNm, 							 		// 문서명
                            bizDvcd               : 'HWM', 							 		// 업무구분코드
                            bizServiceId          : bizServiceId,   // 연관 업무서비스ID
                            aprHistId             : null,						 	 		// 결재이력ID
                            approvalLineRecords   : approvalLineGrid.getJsonAllRecords(), 	// 결재선 그리드 데이터
                            docData               : {								 		// 결재문서 데이터
                                fieldValues       : vm.get('fieldValues'),
                                beforechange      : null,
                                afterchange       : afterchange 			 // 결재문서 필드값
                            }
                        });
                    }
                }

            }
        });
    },

