    /* 보고 버튼 클릭 이벤트 */
    onBtnReptTap: function(button, e, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences();

        var params = {};
        params.wrkDt = me.dateToTimeTable(refs.aplHodDt.getValue(), "");
        params.wrkStrtm = DateUtils.encodeDate(refs.hodStrtm.getValue()).substr(11,8).replace(/:/g,'');
        params.hrHrpmEmpId = SecurityUtils.getPrincipal().hrHrpmEmpId;
        params.sttDate = me.dateToTimeTable(new Date(), "");
        params.aplDvcd = refs.aplDvcd.getValue();
        params.reptType = 'HOD';
        params.aplDt = Ext.Date.format(new Date(), 'Ymd');

        Ext.Ajax.request({
            headers : {
                serviceId : 'HwmOvtSvc.findOneHwmOvtRept',
                viewId : 'HwmHodAply02M'
            },
            scope : me,
            jsonData : params,
            success : function(response) {
                var ob = JSON.parse(response.responseText);
                var wrkDay = ob.wrkDay;
                var ovtHodMap = ob.ovtHodMap;


                var aplHodDt = DateUtils.getDate(refs.aplHodDt.getValue());
                var aplHodStrtm = refs.hodStrtm.getValue();
                var hh = aplHodStrtm.getHours()+"";
                var mi = aplHodStrtm.getMinutes()+"";
                hh = (hh.length == 1 ? '0' : "") + hh;
                mi = (mi.length == 1 ? '0' : "") + mi;

                aplHodStrtm = hh + "" + mi;   //TODO : datetimeFormat convert 함수 만들기


                if(wrkDay && wrkDay.wrkEdt){
                    if(aplHodDt == wrkDay.wrkDt && (new Date(wrkDay.wrkStrdt).getTime() >= new Date(wrkDay.wrkEdt).getTime()) && (new Date(aplHodStrtm).getTime() >= new Date(wrkDay.wrkEdtm.replace(':','')).getTime())){
                        //update by jihyun
                        Ext.Msg.alert("안내", "퇴근일시가 휴일근무 시작일시보다 이전이면 <br> 휴일근무 보고를 할 수 없습니다.");
                        return;
                    }
                    me.setReptComponent(e);
                    refs.wrkStrdt.setValue(wrkDay.wrkStrdt);
                    refs.wrkEdt.setValue(wrkDay.wrkEdt);
                    refs.wrkStrtm.setValue(wrkDay.wrkStrtm);
                    refs.wrkEdtm.setValue(wrkDay.wrkEdtm);
                } else if(e !== null){
                    msg = "해당일자에 출퇴근 정보가 존재하지 않습니다.";
                    Ext.Msg.alert("유효성 검증", msg);
                    return;
                }

                refs.totOvtHodMonthDds.setValue(ovtHodMap.monthDds);
                refs.totOvtHodMonthHr.setValue(ovtHodMap.monthHr);
                refs.totOvtHodWeekDds.setValue(ovtHodMap.weekDds);
                refs.totOvtHodWeekHr.setValue(ovtHodMap.weekHr);

                //         if(wrkMnth){
                //             refs.totOvtHr.setHtml(wrkMnth.totOvtHr);
                //             refs.totHodHr.setHtml(wrkMnth.totHodHr);
                //         }
            }
        });

    },

